var e={name:"llama-server",description:"OpenAI-compatible HTTP server for llama.cpp models",options:[{name:["-h","--help","--usage"],description:"Print usage and exit"},{name:"--version",description:"Show version and build info"},{name:["-cl","--cache-list"],description:"Show list of models in cache"},{name:"--completion-bash",description:"Print source-able bash completion script for llama.cpp"},{name:["-t","--threads"],description:"Number of CPU threads to use during generation (default: -1)",args:{name:"n"}},{name:["-tb","--threads-batch"],description:"Number of threads to use during batch and prompt processing (default: same as --threads)",args:{name:"n"}},{name:["-C","--cpu-mask"],description:'CPU affinity mask: arbitrarily long hex. Complements cpu-range (default: "")',args:{name:"m"}},{name:["-Cr","--cpu-range"],description:"Range of CPUs for affinity. Complements --cpu-mask",args:{name:"lo-hi"}},{name:"--cpu-strict",description:"Use strict CPU placement (default: 0)",args:{name:"value",suggestions:["0","1"]}},{name:"--prio",description:"Set process/thread priority : low(-1), normal(0), medium(1), high(2), realtime(3) (default: 0)",args:{name:"n"}},{name:"--poll",description:"Use polling level to wait for work (0 - no polling, default: 50)",args:{name:"value"}},{name:["-Cb","--cpu-mask-batch"],description:"CPU affinity mask: arbitrarily long hex. Complements cpu-range-batch (default: same as --cpu-mask)",args:{name:"m"}},{name:["-Crb","--cpu-range-batch"],description:"Ranges of CPUs for affinity. Complements --cpu-mask-batch",args:{name:"lo-hi"}},{name:"--cpu-strict-batch",description:"Use strict CPU placement (default: same as --cpu-strict)",args:{name:"value",suggestions:["0","1"]}},{name:"--prio-batch",description:"Set process/thread priority : 0-normal, 1-medium, 2-high, 3-realtime (default: 0)",args:{name:"n"}},{name:"--poll-batch",description:"Use polling to wait for work (default: same as --poll)",args:{name:"value",suggestions:["0","1"]}},{name:["-c","--ctx-size"],description:"Size of the prompt context (default: 0, 0 = loaded from model)",args:{name:"n"}},{name:["-n","--predict","--n-predict"],description:"Number of tokens to predict (default: -1, -1 = infinity)",args:{name:"n"}},{name:["-b","--batch-size"],description:"Logical maximum batch size (default: 2048)",args:{name:"n"}},{name:["-ub","--ubatch-size"],description:"Physical maximum batch size (default: 512)",args:{name:"n"}},{name:"--keep",description:"Number of tokens to keep from the initial prompt (default: 0, -1 = all)",args:{name:"n"}},{name:"--swa-full",description:"Use full-size SWA cache (default: false)"},{name:["-fa","--flash-attn"],description:"Set Flash Attention use ('on', 'off', or 'auto', default: 'auto')",args:{name:"value",suggestions:["on","off","auto"],isOptional:!0}},{name:["--perf","--no-perf"],description:"Whether to enable internal libllama performance timings (default: false)"},{name:["-e","--escape","--no-escape"],description:`Whether to process escapes sequences (\\n, \\r, \\t, \\', \\", \\\\) (default: true)`},{name:"--rope-scaling",description:"RoPE frequency scaling method, defaults to linear unless specified by the model",args:{name:"value",suggestions:["none","linear","yarn"]}},{name:"--rope-scale",description:"RoPE context scaling factor, expands context by a factor of N",args:{name:"n"}},{name:"--rope-freq-base",description:"RoPE base frequency, used by NTK-aware scaling (default: loaded from model)",args:{name:"n"}},{name:"--rope-freq-scale",description:"RoPE frequency scaling factor, expands context by a factor of 1/N",args:{name:"n"}},{name:"--yarn-orig-ctx",description:"YaRN: original context size of model (default: 0 = model training context size)",args:{name:"n"}},{name:"--yarn-ext-factor",description:"YaRN: extrapolation mix factor (default: -1.00, 0.0 = full interpolation)",args:{name:"n"}},{name:"--yarn-attn-factor",description:"YaRN: scale sqrt(t) or attention magnitude (default: -1.00)",args:{name:"n"}},{name:"--yarn-beta-slow",description:"YaRN: high correction dim or alpha (default: -1.00)",args:{name:"n"}},{name:"--yarn-beta-fast",description:"YaRN: low correction dim or beta (default: -1.00)",args:{name:"n"}},{name:["-kvo","--kv-offload","-nkvo","--no-kv-offload"],description:"Whether to enable KV cache offloading (default: enabled)"},{name:["--repack","-nr","--no-repack"],description:"Whether to enable weight repacking (default: enabled)"},{name:"--no-host",description:"Bypass host buffer allowing extra buffers to be used"},{name:["-ctk","--cache-type-k"],description:"KV cache data type for K allowed values: f32, f16, bf16, q8_0, q4_0, q4_1, iq4_nl, q5_0, q5_1 (default: f16)",args:{name:"type"}},{name:["-ctv","--cache-type-v"],description:"KV cache data type for V allowed values: f32, f16, bf16, q8_0, q4_0, q4_1, iq4_nl, q5_0, q5_1 (default: f16)",args:{name:"type"}},{name:["-dt","--defrag-thold"],description:"KV cache defragmentation threshold (DEPRECATED)",args:{name:"n"}},{name:"--mlock",description:"DEPRECATED in favor of `--load-mode`: force system to keep model in RAM rather than swapping or compressing"},{name:["--mmap","--no-mmap"],description:"DEPRECATED in favor of `--load-mode`: whether to memory-map model. (if mmap disabled, slower load but may reduce pageouts if not using mlock)"},{name:["-dio","--direct-io","-ndio","--no-direct-io"],description:"DEPRECATED in favor of `--load-mode`: use DirectIO if available"},{name:["-lm","--load-mode"],description:"Model loading mode (default: auto) - auto: mmap, unless a device does not support it - none: no special loading mode - mmap: memory-map model (if mmap disabl",args:{name:"mode"}},{name:"--numa",description:"Attempt optimizations that help on some NUMA systems - distribute: spread execution evenly over all nodes - isolate: only spawn threads on CPUs on the node t",args:{name:"type"}},{name:["-dev","--device"],description:"Comma-separated list of devices to use for offloading (none = don't offload) use --list-devices to see a list of available devices",args:{name:"value"}},{name:"--list-devices",description:"Print list of available devices and exit"},{name:["-ot","--override-tensor"],description:"Override tensor buffer type",args:{name:"value"}},{name:["-cmoe","--cpu-moe"],description:"Keep all Mixture of Experts (MoE) weights in the CPU"},{name:["-ncmoe","--n-cpu-moe"],description:"Keep the Mixture of Experts (MoE) weights of the first N layers in the CPU",args:{name:"n"}},{name:["-ngl","--gpu-layers","--n-gpu-layers"],description:"Max. number of layers to store in VRAM, either an exact number, 'auto', or 'all' (default: auto)",args:{name:"n"}},{name:["-sm","--split-mode"],description:"How to split the model across multiple GPUs, one of: - none: use one GPU only - layer (default): split layers and KV across GPUs (pipelined) - row: split wei",args:{name:"value",suggestions:["none","layer","row","tensor"]}},{name:["-ts","--tensor-split"],description:"Fraction of the model to offload to each GPU, comma-separated list of proportions, e.g. 3,1",args:{name:"n0_n1_n2_..."}},{name:["-mg","--main-gpu"],description:"The GPU to use for the model (with split-mode = none), or for intermediate results and KV (with split-mode = row) (default: 0)",args:{name:"index"}},{name:["-fit","--fit"],description:"Whether to adjust unset arguments to fit in device memory ('on' or 'off', default: 'on')",args:{name:"value",suggestions:["on","off"],isOptional:!0}},{name:["-fitt","--fit-target"],description:"Target margin per device for --fit, comma-separated list of values, single value is broadcast across all devices, default: 1024",args:{name:"mib0_mib1_mib2_..."}},{name:["-fitc","--fit-ctx"],description:"Minimum ctx size that can be set by --fit option, default: 4096",args:{name:"n"}},{name:"--check-tensors",description:"Check model tensor data for invalid values (default: false)"},{name:"--override-kv",description:"Advanced option to override model metadata by key. to specify multiple overrides, either use comma-separated values. types: int, float, bool, str. example: -",args:{name:"key_type_value_..."}},{name:["--op-offload","--no-op-offload"],description:"Whether to offload host tensor operations to device (default: true)"},{name:"--lora",description:"Path to LoRA adapter (use comma-separated values to load multiple adapters)",args:{name:"fname",template:"filepaths"}},{name:"--lora-scaled",description:"Path to LoRA adapter with user defined scaling (format: FNAME:SCALE,...) note: use comma-separated values",args:{name:"fname",template:"filepaths"}},{name:"--control-vector",description:"Add a control vector note: use comma-separated values to add multiple control vectors",args:{name:"fname",template:"filepaths"}},{name:"--control-vector-scaled",description:"Add a control vector with user defined scaling SCALE note: use comma-separated values (format: FNAME:SCALE,...)",args:{name:"fname",template:"filepaths"}},{name:"--control-vector-layer-range",description:"Layer range to apply the control vector(s) to, start and end inclusive",args:{name:"start_end"}},{name:["-m","--model"],description:"Model path to load",args:{name:"fname",template:"filepaths"}},{name:["-mu","--model-url"],description:"Model download url (default: unused)",args:{name:"model_url"}},{name:["-dr","--docker-repo"],description:"Docker Hub model repository. repo is optional, default to ai/. quant is optional, default to :latest. example: gemma3 (default: unused)",args:{name:"repo/model"}},{name:["-hf","-hfr","--hf-repo"],description:"Hugging Face model repository; quant is optional, case-insensitive, default to Q4_K_M, or falls back to the first file in the repo if Q4_K_M doesn't exist. m",args:{name:"user/model"}},{name:["-hff","--hf-file"],description:"Hugging Face model file. If specified, it will override the quant in --hf-repo (default: unused)",args:{name:"file"}},{name:["-hft","--hf-token"],description:"Hugging Face access token (default: value from HF_TOKEN environment variable)",args:{name:"token"}},{name:"--log-disable",description:"Log disable"},{name:"--log-file",description:"Log to file",args:{name:"fname",template:"filepaths"}},{name:"--log-colors",description:"Set colored logging ('on', 'off', or 'auto', default: 'auto') 'auto' enables colors when output is to a terminal",args:{name:"value",suggestions:["on","off","auto"],isOptional:!0}},{name:["-v","--verbose","--log-verbose"],description:"Set verbosity level to infinity (i.e. log all messages, useful for debugging)"},{name:"--offline",description:"Offline mode: forces use of cache, prevents network access"},{name:["-lv","--verbosity","--log-verbosity"],description:"Set the verbosity threshold. Messages with a higher verbosity will be ignored. Values: - 0: generic output - 1: error - 2: warning - 3: info - 4: trace",args:{name:"n"}},{name:["--log-prefix","--no-log-prefix"],description:"Enable prefix in log messages"},{name:["--log-timestamps","--no-log-timestamps"],description:"Enable timestamps in log messages"},{name:["--spec-draft-type-k","-ctkd","--cache-type-k-draft"],description:"KV cache data type for K for the draft model allowed values: f32, f16, bf16, q8_0, q4_0, q4_1, iq4_nl, q5_0, q5_1 (default: f16)",args:{name:"type"}},{name:["--spec-draft-type-v","-ctvd","--cache-type-v-draft"],description:"KV cache data type for V for the draft model allowed values: f32, f16, bf16, q8_0, q4_0, q4_1, iq4_nl, q5_0, q5_1 (default: f16)",args:{name:"type"}},{name:"--samplers",description:"Samplers that will be used for generation in the order, separated by ';' (default: penalties;dry;top_n_sigma;top_k;typ_p;top_p;min_p;xtc;temperature)",args:{name:"samplers"}},{name:["-s","--seed"],description:"RNG seed (default: -1, use random seed for -1)",args:{name:"seed"}},{name:["--sampler-seq","--sampling-seq"],description:"Simplified sequence for samplers that will be used (default: edskypmxt)",args:{name:"sequence"}},{name:"--ignore-eos",description:"Ignore end of stream token and continue generating (implies --logit-bias EOS-inf)"},{name:["--temp","--temperature"],description:"Temperature (default: 0.80)",args:{name:"n"}},{name:"--top-k",description:"Top-k sampling (default: 40, 0 = disabled)",args:{name:"n"}},{name:"--top-p",description:"Top-p sampling (default: 0.95, 1.0 = disabled)",args:{name:"n"}},{name:"--min-p",description:"Min-p sampling (default: 0.05, 0.0 = disabled)",args:{name:"n"}},{name:["--top-nsigma","--top-n-sigma"],description:"Top-n-sigma sampling (default: -1.00, -1.0 = disabled)",args:{name:"n"}},{name:"--xtc-probability",description:"Xtc probability (default: 0.00, 0.0 = disabled)",args:{name:"n"}},{name:"--xtc-threshold",description:"Xtc threshold (default: 0.10, 1.0 = disabled)",args:{name:"n"}},{name:["--typical","--typical-p"],description:"Locally typical sampling, parameter p (default: 1.00, 1.0 = disabled)",args:{name:"n"}},{name:"--repeat-last-n",description:"Last n tokens to consider for penalize (default: 64, 0 = disabled)",args:{name:"n"}},{name:"--repeat-penalty",description:"Penalize repeat sequence of tokens (default: 1.00, 1.0 = disabled)",args:{name:"n"}},{name:"--presence-penalty",description:"Repeat alpha presence penalty (default: 0.00, 0.0 = disabled)",args:{name:"n"}},{name:"--frequency-penalty",description:"Repeat alpha frequency penalty (default: 0.00, 0.0 = disabled)",args:{name:"n"}},{name:"--dry-multiplier",description:"Set DRY sampling multiplier (default: 0.00, 0.0 = disabled)",args:{name:"n"}},{name:"--dry-base",description:"Set DRY sampling base value (default: 1.75)",args:{name:"n"}},{name:"--dry-allowed-length",description:"Set allowed length for DRY sampling (default: 2)",args:{name:"n"}},{name:"--dry-penalty-last-n",description:"Set DRY penalty for the last n tokens (default: 64, 0 = disable)",args:{name:"n"}},{name:"--dry-sequence-breaker",description:`Add sequence breaker for DRY sampling, clearing out default breakers ('\\n', ':', '"', '*') in the process; use "none" to not use any sequence breakers`,args:{name:"string"}},{name:"--adaptive-target",description:"Adaptive-p: select tokens near this probability (valid range 0.0 to 1.0; negative = disabled) (default: -1.00)",args:{name:"n"}},{name:"--adaptive-decay",description:"Adaptive-p: decay rate for target adaptation over time. lower values are more reactive, higher values are more stable. (valid range 0.0 to 0.99) (default: 0.90)",args:{name:"n"}},{name:"--dynatemp-range",description:"Dynamic temperature range (default: 0.00, 0.0 = disabled)",args:{name:"n"}},{name:"--dynatemp-exp",description:"Dynamic temperature exponent (default: 1.00)",args:{name:"n"}},{name:"--mirostat",description:"Use Mirostat sampling. Top K, Nucleus and Locally Typical samplers are ignored if used. (default: 0, 0 = disabled, 1 = Mirostat, 2 = Mirostat 2.0)",args:{name:"n"}},{name:"--mirostat-lr",description:"Mirostat learning rate, parameter eta (default: 0.10)",args:{name:"n"}},{name:"--mirostat-ent",description:"Mirostat target entropy, parameter tau (default: 5.00)",args:{name:"n"}},{name:["-l","--logit-bias"],description:"Modifies the likelihood of token appearing in the completion, i.e. `--logit-bias 15043+1` to increase likelihood of token ' Hello', or `--logit-bias 15043-1`",args:{name:"token_id___-_bias"}},{name:"--grammar",description:"BNF-like grammar to constrain generations (see samples in grammars/ dir)",args:{name:"grammar"}},{name:"--grammar-file",description:"File to read grammar from",args:{name:"fname",template:"filepaths"}},{name:["-j","--json-schema"],description:"JSON schema to constrain generations ( e.g. `{}` for any JSON object For schemas w/ external $refs, use --grammar + example/json_schema_to_grammar.py instead",args:{name:"schema"}},{name:["-jf","--json-schema-file"],description:"File containing a JSON schema to constrain generations ( e.g. `{}` for any JSON object For schemas w/ external $refs, use --grammar + example/json_schema_to_",args:{name:"file"}},{name:["-bs","--backend-sampling"],description:"Enable backend sampling (experimental) (default: disabled)"},{name:["--spec-draft-hf","-hfd","-hfrd","--hf-repo-draft"],description:"Same as --hf-repo, but for the draft model (default: unused)",args:{name:"user/model"}},{name:["--spec-draft-threads","-td","--threads-draft"],description:"Number of threads to use during generation (default: same as --threads)",args:{name:"n"}},{name:["--spec-draft-threads-batch","-tbd","--threads-batch-draft"],description:"Number of threads to use during batch and prompt processing (default: same as --threads-draft)",args:{name:"n"}},{name:["--spec-draft-cpu-mask","-Cd","--cpu-mask-draft"],description:"Draft model CPU affinity mask. Complements cpu-range-draft (default: same as --cpu-mask)",args:{name:"m"}},{name:["--spec-draft-cpu-range","-Crd","--cpu-range-draft"],description:"Ranges of CPUs for affinity. Complements --cpu-mask-draft",args:{name:"lo-hi"}},{name:["--spec-draft-cpu-strict","--cpu-strict-draft"],description:"Use strict CPU placement for draft model (default: same as --cpu-strict)",args:{name:"value",suggestions:["0","1"]}},{name:["--spec-draft-prio","--prio-draft"],description:"Set draft process/thread priority : 0-normal, 1-medium, 2-high, 3-realtime (default: 0)",args:{name:"n"}},{name:["--spec-draft-poll","--poll-draft"],description:"Use polling to wait for draft model work (default: same as --poll)",args:{name:"value",suggestions:["0","1"]}},{name:["--spec-draft-cpu-mask-batch","-Cbd","--cpu-mask-batch-draft"],description:"Draft model CPU affinity mask. Complements cpu-range-draft (default: same as --cpu-mask)",args:{name:"m"}},{name:["--spec-draft-cpu-strict-batch","--cpu-strict-batch-draft"],description:"Use strict CPU placement for draft model (default: --cpu-strict-draft)",args:{name:"value",suggestions:["0","1"]}},{name:["--spec-draft-prio-batch","--prio-batch-draft"],description:"Set draft process/thread priority : 0-normal, 1-medium, 2-high, 3-realtime (default: 0)",args:{name:"n"}},{name:["--spec-draft-poll-batch","--poll-batch-draft"],description:"Use polling to wait for draft model work (default: --poll-draft)",args:{name:"value",suggestions:["0","1"]}},{name:["--spec-draft-override-tensor","-otd","--override-tensor-draft"],description:"Override tensor buffer type for draft model",args:{name:"value"}},{name:["--spec-draft-cpu-moe","-cmoed","--cpu-moe-draft"],description:"Keep all Mixture of Experts (MoE) weights in the CPU for the draft model"},{name:["--spec-draft-n-cpu-moe","--spec-draft-ncmoe","-ncmoed","--n-cpu-moe-draft"],description:"Keep the Mixture of Experts (MoE) weights of the first N layers in the CPU for the draft model",args:{name:"n"}},{name:"--spec-draft-n-max",description:"Number of tokens to draft for speculative decoding (default: 3)",args:{name:"n"}},{name:"--spec-draft-n-min",description:"Minimum number of draft tokens to use for speculative decoding (default: 0)",args:{name:"n"}},{name:["--spec-draft-p-split","--draft-p-split"],description:"Speculative decoding split probability (default: 0.10)",args:{name:"p"}},{name:["--spec-draft-p-min","--draft-p-min"],description:"Minimum speculative decoding probability (greedy) (default: 0.00)",args:{name:"p"}},{name:["--spec-draft-backend-sampling","--no-spec-draft-backend-sampling"],description:"Offload draft sampling to the backend (default: enabled)"},{name:["--spec-draft-device","-devd","--device-draft"],description:"Comma-separated list of devices to use for offloading the draft model (none = don't offload) use --list-devices to see a list of available devices",args:{name:"value"}},{name:["--spec-draft-ngl","-ngld","--gpu-layers-draft","--n-gpu-layers-draft"],description:"Max. number of draft model layers to store in VRAM, either an exact number, 'auto', or 'all' (default: auto)",args:{name:"n"}},{name:["--spec-draft-model","-md","--model-draft"],description:"Draft model for speculative decoding (default: unused)",args:{name:"fname",template:"filepaths"}},{name:"--spec-type",description:"Comma-separated list of types of speculative decoding to use (default: none)",args:{name:"value"}},{name:"--spec-ngram-mod-n-min",description:"Minimum number of ngram tokens to use for ngram-based speculative decoding (default: 48)",args:{name:"n"}},{name:"--spec-ngram-mod-n-max",description:"Maximum number of ngram tokens to use for ngram-based speculative decoding (default: 64)",args:{name:"n"}},{name:"--spec-ngram-mod-n-match",description:"Ngram-mod lookup length (default: 24)",args:{name:"n"}},{name:"--spec-ngram-simple-size-n",description:"Ngram size N for ngram-simple speculative decoding, length of lookup n-gram (default: 12)",args:{name:"n"}},{name:"--spec-ngram-simple-size-m",description:"Ngram size M for ngram-simple speculative decoding, length of draft m-gram (default: 48)",args:{name:"n"}},{name:"--spec-ngram-simple-min-hits",description:"Minimum hits for ngram-simple speculative decoding (default: 1)",args:{name:"n"}},{name:"--spec-ngram-map-k-size-n",description:"Ngram size N for ngram-map-k speculative decoding, length of lookup n-gram (default: 12)",args:{name:"n"}},{name:"--spec-ngram-map-k-size-m",description:"Ngram size M for ngram-map-k speculative decoding, length of draft m-gram (default: 48)",args:{name:"n"}},{name:"--spec-ngram-map-k-min-hits",description:"Minimum hits for ngram-map-k speculative decoding (default: 1)",args:{name:"n"}},{name:"--spec-ngram-map-k4v-size-n",description:"Ngram size N for ngram-map-k4v speculative decoding, length of lookup n-gram (default: 12)",args:{name:"n"}},{name:"--spec-ngram-map-k4v-size-m",description:"Ngram size M for ngram-map-k4v speculative decoding, length of draft m-gram (default: 48)",args:{name:"n"}},{name:"--spec-ngram-map-k4v-min-hits",description:"Minimum hits for ngram-map-k4v speculative decoding (default: 1)",args:{name:"n"}},{name:["--draft","--draft-n","--draft-max"],description:"The argument has been removed. use --spec-draft-n-max or --spec-ngram-mod-n-max",args:{name:"n"}},{name:["--draft-min","--draft-n-min"],description:"The argument has been removed. use --spec-draft-n-min or --spec-ngram-mod-n-min",args:{name:"n"}},{name:"--spec-ngram-size-n",description:"The argument has been removed. use the respective --spec-ngram-*-size-n or --spec-ngram-mod-n-match",args:{name:"n"}},{name:"--spec-ngram-size-m",description:"The argument has been removed. use the respective --spec-ngram-*-size-m",args:{name:"n"}},{name:"--spec-ngram-min-hits",description:"The argument has been removed. use the respective --spec-ngram-*-min-hits",args:{name:"n"}},{name:["-lcs","--lookup-cache-static"],description:"Path to static lookup cache to use for lookup decoding (not updated by generation)",args:{name:"fname",template:"filepaths"}},{name:["-lcd","--lookup-cache-dynamic"],description:"Path to dynamic lookup cache to use for lookup decoding (updated by generation)",args:{name:"fname",template:"filepaths"}},{name:["-ctxcp","--ctx-checkpoints","--swa-checkpoints"],description:"Max number of context checkpoints to create per slot (default: 32)",args:{name:"n"}},{name:["-cms","--checkpoint-min-step"],description:"Minimum spacing between context checkpoints in tokens (default: 8192, 0 = no minimum)",args:{name:"n"}},{name:["-cram","--cache-ram"],description:"Set the maximum cache size in MiB (default: 8192, -1 - no limit, 0 - disable)",args:{name:"n"}},{name:["-kvu","--kv-unified","-no-kvu","--no-kv-unified"],description:"Use single unified KV buffer shared across all sequences (default: enabled if number of slots is auto)"},{name:["--cache-idle-slots","--no-cache-idle-slots"],description:"Save idle slots to the prompt cache on new task, and clear them when using unified KV (default: enabled, requires cache-ram)"},{name:["--context-shift","--no-context-shift"],description:"Whether to use context shift on infinite text generation (default: disabled)"},{name:["-r","--reverse-prompt"],description:"Halt generation at PROMPT, return control in interactive mode",args:{name:"prompt"}},{name:["-sp","--special"],description:"Special tokens output enabled (default: false)"},{name:["--warmup","--no-warmup"],description:"Whether to perform warmup with an empty run (default: enabled)"},{name:"--spm-infill",description:"Use Suffix/Prefix/Middle pattern for infill (instead of Prefix/Suffix/Middle) as some models prefer this. (default: disabled)"},{name:"--pooling",description:"Pooling type for embeddings, use model default if unspecified",args:{name:"value",suggestions:["none","mean","cls","last","rank"]}},{name:["-np","--parallel"],description:"Number of server slots (default: -1, -1 = auto)",args:{name:"n"}},{name:["-cb","--cont-batching","-nocb","--no-cont-batching"],description:"Whether to enable continuous batching (a.k.a dynamic batching) (default: enabled)"},{name:["-mm","--mmproj"],description:"Path to a multimodal projector file. see tools/mtmd/README.md note: if -hf is used, this argument can be omitted",args:{name:"file"}},{name:["-mmu","--mmproj-url"],description:"URL to a multimodal projector file. see tools/mtmd/README.md",args:{name:"url"}},{name:["--mmproj-auto","--no-mmproj","--no-mmproj-auto"],description:"Whether to use multimodal projector file (if available), useful when using -hf (default: enabled)"},{name:["--mmproj-offload","--no-mmproj-offload"],description:"Whether to enable GPU offloading for multimodal projector (default: enabled)"},{name:["-mmdev","--mmproj-device"],description:"Device to use for multimodal projector (none = don't offload, default: auto) use --list-devices to see a list of available devices",args:{name:"device"}},{name:"--image-min-tokens",description:"Minimum number of tokens each image can take, only used by vision models with dynamic resolution (default: read from model)",args:{name:"n"}},{name:"--image-max-tokens",description:"Maximum number of tokens each image can take, only used by vision models with dynamic resolution (default: read from model)",args:{name:"n"}},{name:"--mtmd-batch-max-tokens",description:"Maximum number of image tokens per batch when encoding images (default: 1024)",args:{name:"n"}},{name:["-a","--alias"],description:"Set model name aliases, comma-separated (to be used by API)",args:{name:"string"}},{name:"--tags",description:"Set model tags, comma-separated (informational, not used for routing)",args:{name:"string"}},{name:"--embd-normalize",description:"Normalisation for embeddings (default: 2) (-1=none, 0=max absolute int16, 1=taxicab, 2=euclidean, >2=p-norm)",args:{name:"n"}},{name:"--host",description:"Ip address to listen, or bind to an UNIX socket if the address ends with .sock (default: 127.0.0.1)",args:{name:"host"}},{name:"--port",description:"Port to listen (default: 8080)",args:{name:"port"}},{name:"--reuse-port",description:"Allow multiple sockets to bind to the same port (default: disabled)"},{name:"--path",description:"Path to serve static files from (default: )",args:{name:"path"}},{name:"--cors-origins",description:"Comma-separated list of allowed origins for CORS (default: *) if set to special value 'localhost', reflect the Origin header only if it is localhost",args:{name:"origins"}},{name:"--cors-methods",description:"Comma-separated list of allowed methods for CORS (default: GET, POST, DELETE, OPTIONS)",args:{name:"methods"}},{name:"--cors-headers",description:"Comma-separated list of allowed headers for CORS (default: *)",args:{name:"headers"}},{name:["--cors-credentials","--no-cors-credentials"],description:"Whether to allow credentials for CORS (default: enabled) note: if this is enabled and --cors-origins is set to * (default), the Origin header will be echoed"},{name:"--api-prefix",description:"Prefix path the server serves from, without the trailing slash (default: )",args:{name:"prefix"}},{name:["--ui-config","--webui-config"],description:"JSON that provides default UI settings (overrides UI defaults)",args:{name:"json"}},{name:["--ui-config-file","--webui-config-file"],description:"JSON file that provides default UI settings (overrides UI defaults)",args:{name:"path"}},{name:["--ui-mcp-proxy","--webui-mcp-proxy","--no-ui-mcp-proxy","--no-webui-mcp-proxy"],description:"Experimental: whether to enable MCP CORS proxy - do not enable in untrusted environments (default: disabled)"},{name:"--tools",description:'Experimental: whether to enable built-in tools for AI agents - do not enable in untrusted environments (default: no tools) specify "all" to enable all tools',args:{name:"tool1_tool2_..."}},{name:"--tools-runtime",description:"Experimental: run tools in a separate runtime environment (default: none, use host environment) available options: 'docker:<image>', 'podman:<image>': spin u",args:{name:"option"}},{name:"--mcp-servers-config",description:"Experimental: path to JSON file with MCP server definitions (Cursor-compatible format) - do not enable in untrusted environments (default: none) note: for se",args:{name:"path"}},{name:"--mcp-servers-json",description:"Experimental: inline JSON with MCP server definitions (Cursor-compatible format) - do not enable in untrusted environments (default: none) note: for security",args:{name:"json"}},{name:["-ag","--agent","-no-ag","--no-agent"],description:"Whether to enable CORS proxy and all built-in tools - do not enable in untrusted environments (default: disabled) note: for security reasons, this will limit"},{name:["--ui","--webui","--no-ui","--no-webui"],description:"Whether to enable the Web UI (default: enabled)"},{name:["--embedding","--embeddings"],description:"Restrict to only support embedding use case; use only with dedicated embedding models (default: disabled)"},{name:["--rerank","--reranking"],description:"Enable reranking endpoint on server (default: disabled)"},{name:"--api-key",description:"API key to use for authentication, multiple keys can be provided as a comma-separated list (default: none)",args:{name:"key"}},{name:"--api-key-file",description:"Path to file containing API keys, one per line; lines starting with a hash are treated as comments (default: none)",args:{name:"fname",template:"filepaths"}},{name:"--ssl-key-file",description:"Path to file a PEM-encoded SSL private key",args:{name:"fname",template:"filepaths"}},{name:"--ssl-cert-file",description:"Path to file a PEM-encoded SSL certificate",args:{name:"fname",template:"filepaths"}},{name:"--chat-template-kwargs",description:`Sets additional params for the json template parser, must be a valid json object string, e.g. '{"key1":"value1","key2":"value2"}'`,args:{name:"string"}},{name:["-to","--timeout"],description:"Server read/write timeout in seconds (default: 3600)",args:{name:"n"}},{name:"--sse-ping-interval",description:"Server SSE ping interval in seconds (-1 = disabled, default: 30)",args:{name:"n"}},{name:"--threads-http",description:"Number of threads used to process HTTP requests (default: -1)",args:{name:"n"}},{name:["--cache-prompt","--no-cache-prompt"],description:"Whether to enable prompt caching (default: enabled)"},{name:"--cache-reuse",description:"Min chunk size to attempt reusing from the cache via KV shifting, requires prompt caching to be enabled (default: 0) [(card)](",args:{name:"n"}},{name:"--metrics",description:"Enable prometheus compatible metrics endpoint (default: disabled)"},{name:"--props",description:"Enable changing global properties via POST /props (default: disabled)"},{name:["--slots","--no-slots"],description:"Expose slots monitoring endpoint (default: enabled)"},{name:"--slot-save-path",description:"Path to save slot kv cache (default: disabled)",args:{name:"path"}},{name:"--media-path",description:"Directory for loading local media files; files can be accessed via file:// URLs using relative paths (default: disabled)",args:{name:"path"}},{name:"--models-dir",description:"Directory containing models for the router server (default: disabled)",args:{name:"path"}},{name:"--models-preset",description:"Path to INI file containing model presets for the router server (default: disabled)",args:{name:"path"}},{name:"--models-max",description:"For router server, maximum number of models to load simultaneously (default: 4, 0 = unlimited)",args:{name:"n"}},{name:["--models-autoload","--no-models-autoload"],description:"For router server, whether to automatically load models (default: enabled)"},{name:["--jinja","--no-jinja"],description:"Whether to use jinja template engine for chat (default: enabled)"},{name:"--reasoning-format",description:"Controls whether thought tags are allowed and/or extracted from the response, and in which format they're returned; one of: - none: leaves thoughts unparsed",args:{name:"format"}},{name:["-rea","--reasoning"],description:"Use reasoning/thinking in the chat ('on', 'off', or 'auto', default: 'auto' (detect from template))",args:{name:"value",suggestions:["on","off","auto"],isOptional:!0}},{name:"--reasoning-effort",description:"Reasoning effort level given to the chat template: 'default' to keep the template default, or a level such as 'minimal', 'low', 'medium', 'high', 'xhigh' or",args:{name:"level"}},{name:"--reasoning-budget",description:"Token budget for thinking: -1 for unrestricted, 0 for immediate end, N>0 for token budget (default: -1)",args:{name:"n"}},{name:"--reasoning-budget-message",description:"Message injected before the end-of-thinking tag when reasoning budget is exhausted (default: none)",args:{name:"message"}},{name:["--reasoning-preserve","--no-reasoning-preserve"],description:"Preserve reasoning trace in the full history, not just the last assistant message (default: template default) compatible with certain templates having 'suppo"},{name:"--chat-template",description:"Set custom jinja chat template (default: template taken from model's metadata) if suffix/prefix are specified, template will be disabled only commonly used t",args:{name:"jinja_template"}},{name:"--chat-template-file",description:"Set custom jinja chat template file (default: template taken from model's metadata) if suffix/prefix are specified, template will be disabled only commonly u",args:{name:"jinja_template_file"}},{name:["--skip-chat-parsing","--no-skip-chat-parsing"],description:"Force a pure content parser, even if a Jinja template is specified; model will output everything in the content section, including any reasoning and/or tool"},{name:["--prefill-assistant","--no-prefill-assistant"],description:"Whether to prefill the assistant's response if the last message is an assistant message (default: prefill enabled) when this flag is set, if the last message"},{name:["-sps","--slot-prompt-similarity"],description:"How much the prompt of a request must match the prompt of a slot in order to use that slot (default: 0.10, 0.0 = disabled)",args:{name:"similarity"}},{name:"--lora-init-without-apply",description:"Load LoRA adapters without applying them (apply later via POST /lora-adapters) (default: disabled)"},{name:"--sleep-idle-seconds",description:"Number of seconds of idleness after which the server will sleep (default: -1; -1 = disabled)",args:{name:"seconds"}},{name:"--log-prompts-dir",description:"Log prompts to directory (auto-created if not present; only used for debugging, default: disabled)",args:{name:"path"}},{name:"--embd-gemma-default",description:"Use default EmbeddingGemma model (note: can download weights from the internet)"},{name:"--fim-qwen-1.5b-default",description:"Use default Qwen 2.5 Coder 1.5B (note: can download weights from the internet)"},{name:"--fim-qwen-3b-default",description:"Use default Qwen 2.5 Coder 3B (note: can download weights from the internet)"},{name:"--fim-qwen-7b-default",description:"Use default Qwen 2.5 Coder 7B (note: can download weights from the internet)"},{name:"--fim-qwen-7b-spec",description:"Use Qwen 2.5 Coder 7B + 0.5B draft for speculative decoding (note: can download weights from the internet)"},{name:"--fim-qwen-14b-spec",description:"Use Qwen 2.5 Coder 14B + 0.5B draft for speculative decoding (note: can download weights from the internet)"},{name:"--fim-qwen-30b-default",description:"Use default Qwen 3 Coder 30B A3B Instruct (note: can download weights from the internet)"},{name:"--gpt-oss-20b-default",description:"Use gpt-oss-20b (note: can download weights from the internet)"},{name:"--gpt-oss-120b-default",description:"Use gpt-oss-120b (note: can download weights from the internet)"},{name:"--vision-gemma-4b-default",description:"Use Gemma 3 4B QAT (note: can download weights from the internet)"},{name:"--vision-gemma-12b-default",description:"Use Gemma 3 12B QAT (note: can download weights from the internet)"},{name:"--spec-default",description:"Enable default speculative decoding config"}]},a=e;export{a as default};
